import type { Workflow, WorkflowNode } from '@/api/types';
import {
  MAX_BATCH_SIZE,
  MIN_BATCH_SIZE,
  type GenerationFormState,
} from '@/hooks/useGenerationForm';
import { findMobileNode, getMobileGenerationProfile } from '@/config/workflowProfile';
import { replaceWorkflowInputLink } from '@/utils/workflowLinks';

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function cloneWorkflow(workflow: Workflow): Workflow {
  if (typeof structuredClone === 'function') return structuredClone(workflow);
  return JSON.parse(JSON.stringify(workflow)) as Workflow;
}

/** Read a canonical widget while accepting both ComfyUI's array and scalar forms. */
export function getGenerationWidgetValue(node: WorkflowNode | undefined, index: number, name?: string): unknown {
  if (!node) return undefined;
  const values = node.widgets_values as unknown;
  if (Array.isArray(values)) return values[index];
  if (isRecord(values)) {
    if (name && values[name] !== undefined) return values[name];
    return values[String(index)];
  }
  return index === 0 ? values : undefined;
}

function setGenerationWidgetValue(node: WorkflowNode, index: number, value: unknown, name?: string): WorkflowNode {
  const values = node.widgets_values as unknown;
  if (Array.isArray(values)) {
    const next = [...values];
    next[index] = value;
    return { ...node, widgets_values: next };
  }
  if (isRecord(values)) {
    return {
      ...node,
      widgets_values: {
        ...values,
        [name ?? String(index)]: value,
      },
    };
  }
  if (index === 0) return { ...node, widgets_values: [value] };
  const next: unknown[] = Array.from({ length: index + 1 }, () => undefined);
  next[index] = value;
  return { ...node, widgets_values: next };
}

function finiteNumber(value: number, fallback: number): number {
  return Number.isFinite(value) ? value : fallback;
}

function clampedInteger(value: number, minimum: number, maximum: number, fallback: number): number {
  if (!Number.isFinite(value)) return fallback;
  return Math.max(minimum, Math.min(maximum, Math.round(value)));
}

function updateNamedNode(
  workflow: Workflow,
  name: string,
  update: (node: WorkflowNode) => WorkflowNode,
): Workflow {
  const index = workflow.nodes.findIndex((node) => {
    const title = typeof node.title === 'string' ? node.title : '';
    const searchName = typeof node.properties?.['Node name for S&R'] === 'string'
      ? node.properties['Node name for S&R']
      : '';
    return title === name || searchName === name;
  });
  if (index < 0) return workflow;
  const nodes = [...workflow.nodes];
  nodes[index] = update(nodes[index]);
  return { ...workflow, nodes };
}

function setMode(workflow: Workflow, name: string, mode: 0 | 4): Workflow {
  return updateNamedNode(workflow, name, (node) => ({ ...node, mode }));
}

interface MobileWorkflowApplyOptions {
  /** Widget name used by the model loader for the form's Checkpoint field. */
  modelWidgetName: 'ckpt_name' | 'unet_name';
  /** Output prefix suffix used to keep SDXL and Anima outputs distinguishable. */
  outputPrefix: 'mobile_sdxl' | 'mobile_anima';
}

/** Apply the shared form mapping to a cloned mobile workflow. */
function applyGenerationFormToWorkflowInternal(
  form: GenerationFormState,
  sourceWorkflow: Workflow,
  options: MobileWorkflowApplyOptions,
  resolvedSeed: number = form.seed,
): Workflow {
  let workflow = cloneWorkflow(sourceWorkflow);
  const { nodeNames } = getMobileGenerationProfile(workflow);

  workflow = updateNamedNode(workflow, nodeNames.checkpoint, (node) =>
    setGenerationWidgetValue(node, 0, form.checkpoint, options.modelWidgetName));
  workflow = updateNamedNode(workflow, nodeNames.positive, (node) =>
    setGenerationWidgetValue(node, 0, form.positivePrompt, 'text'));
  workflow = updateNamedNode(workflow, nodeNames.negative, (node) =>
    setGenerationWidgetValue(node, 0, form.negativePrompt, 'text'));
  const facePositivePrompt = form.facePositivePrompt.trim() !== ''
    ? form.facePositivePrompt
    : form.positivePrompt;
  const faceNegativePrompt = form.faceNegativePrompt.trim() !== ''
    ? form.faceNegativePrompt
    : form.negativePrompt;
  workflow = updateNamedNode(workflow, nodeNames.facePositive, (node) =>
    setGenerationWidgetValue(node, 0, facePositivePrompt, 'text'));
  workflow = updateNamedNode(workflow, nodeNames.faceNegative, (node) =>
    setGenerationWidgetValue(node, 0, faceNegativePrompt, 'text'));

  workflow = updateNamedNode(workflow, nodeNames.size, (node) => {
    let next = setGenerationWidgetValue(node, 0, Math.round(finiteNumber(form.width, 1024)), 'width');
    next = setGenerationWidgetValue(next, 1, Math.round(finiteNumber(form.height, 1536)), 'height');
    return setGenerationWidgetValue(
      next,
      2,
      clampedInteger(form.batchSize, MIN_BATCH_SIZE, MAX_BATCH_SIZE, MIN_BATCH_SIZE),
      'batch_size',
    );
  });

  workflow = updateNamedNode(workflow, nodeNames.baseSampler, (node) => {
    let next = setGenerationWidgetValue(node, 0, Math.round(finiteNumber(resolvedSeed, 0)), 'seed');
    next = setGenerationWidgetValue(next, 2, Math.round(finiteNumber(form.steps, 28)), 'steps');
    next = setGenerationWidgetValue(next, 3, finiteNumber(form.cfg, 5), 'cfg');
    next = setGenerationWidgetValue(next, 4, form.sampler, 'sampler_name');
    return setGenerationWidgetValue(next, 5, form.scheduler, 'scheduler');
  });

  nodeNames.loraSlots.forEach((name, index) => {
    const lora = form.loras[index];
    workflow = setMode(workflow, name, lora.enabled ? 0 : 4);
    workflow = updateNamedNode(workflow, name, (node) => {
      let next = setGenerationWidgetValue(node, 0, lora.name, 'lora_name');
      next = setGenerationWidgetValue(next, 1, finiteNumber(lora.strengthModel, 1), 'strength_model');
      return setGenerationWidgetValue(next, 2, finiteNumber(lora.strengthClip, 1), 'strength_clip');
    });
  });

  const latentHiresEnabled = form.hiresEnabled && form.hiresMode === 'latent';
  const resizeHiresEnabled = form.hiresEnabled && form.hiresMode === 'resize';
  workflow = setMode(workflow, nodeNames.hiresUpscale, latentHiresEnabled ? 0 : 4);
  workflow = setMode(workflow, nodeNames.hiresSampler, latentHiresEnabled ? 0 : 4);
  workflow = updateNamedNode(workflow, nodeNames.hiresUpscale, (node) =>
    setGenerationWidgetValue(node, 1, finiteNumber(form.hiresScale, 1.5), 'scale_by'));
  workflow = updateNamedNode(workflow, nodeNames.hiresSampler, (node) => {
    let next = setGenerationWidgetValue(node, 0, Math.round(finiteNumber(resolvedSeed, 0)), 'seed');
    next = setGenerationWidgetValue(next, 2, Math.round(finiteNumber(form.hiresSteps, 15)), 'steps');
    next = setGenerationWidgetValue(next, 3, finiteNumber(form.hiresCfg, 5), 'cfg');
    next = setGenerationWidgetValue(next, 4, form.hiresSampler, 'sampler_name');
    next = setGenerationWidgetValue(next, 5, form.hiresScheduler, 'scheduler');
    return setGenerationWidgetValue(next, 6, finiteNumber(form.hiresDenoise, 0.35), 'denoise');
  });
  workflow = setMode(workflow, nodeNames.hiresResizeDecode, resizeHiresEnabled ? 0 : 4);
  workflow = setMode(workflow, nodeNames.hiresResizeImage, resizeHiresEnabled ? 0 : 4);
  workflow = setMode(workflow, nodeNames.hiresResizeEncode, resizeHiresEnabled ? 0 : 4);
  workflow = setMode(workflow, nodeNames.hiresResizeSampler, resizeHiresEnabled ? 0 : 4);
  workflow = updateNamedNode(workflow, nodeNames.hiresResizeImage, (node) => {
    const next = setGenerationWidgetValue(node, 0, form.resizeMethod, 'upscale_method');
    return setGenerationWidgetValue(next, 1, finiteNumber(form.hiresScale, 1.5), 'scale_by');
  });
  workflow = updateNamedNode(workflow, nodeNames.hiresResizeSampler, (node) => {
    let next = setGenerationWidgetValue(node, 0, Math.round(finiteNumber(resolvedSeed, 0)), 'seed');
    next = setGenerationWidgetValue(next, 2, Math.round(finiteNumber(form.hiresSteps, 15)), 'steps');
    next = setGenerationWidgetValue(next, 3, finiteNumber(form.hiresCfg, 5), 'cfg');
    next = setGenerationWidgetValue(next, 4, form.hiresSampler, 'sampler_name');
    next = setGenerationWidgetValue(next, 5, form.hiresScheduler, 'scheduler');
    return setGenerationWidgetValue(next, 6, finiteNumber(form.hiresDenoise, 0.35), 'denoise');
  });

  // The canonical workflow has no frontend-only ComfySwitchNode. Select the
  // final latent at the real consumer instead, so bypassed branch nodes never
  // leave a prompt input pointing at a node that buildPromptFromWorkflow drops.
  const finalLatentNodeName = !form.hiresEnabled
    ? nodeNames.baseSampler
    : form.hiresMode === 'latent'
      ? nodeNames.hiresSampler
      : nodeNames.hiresResizeSampler;
  workflow = replaceNamedWorkflowInputLink(
    workflow,
    nodeNames.vaeDecode,
    'samples',
    finalLatentNodeName,
    'LATENT',
  );

  // Keep old switch widgets restorable for workflows created before the
  // canonical graph stopped using ComfySwitchNode. They are not present in
  // the bundled execution workflow and therefore cannot enter its prompt.
  workflow = updateLegacyHiresSwitches(workflow, nodeNames, form);

  workflow = updateNamedNode(workflow, nodeNames.faceDetector, (node) =>
    setGenerationWidgetValue(node, 0, 'bbox/face_yolov8m.pt', 'model_name'));
  workflow = setMode(workflow, nodeNames.faceDetailer, form.faceDetailerEnabled ? 0 : 4);
  workflow = setMode(workflow, nodeNames.facePositive, form.faceDetailerEnabled ? 0 : 4);
  workflow = setMode(workflow, nodeNames.faceNegative, form.faceDetailerEnabled ? 0 : 4);
  workflow = replaceNamedWorkflowInputLink(
    workflow,
    nodeNames.faceDetailer,
    'positive',
    nodeNames.facePositive,
    'CONDITIONING',
  );
  workflow = replaceNamedWorkflowInputLink(
    workflow,
    nodeNames.faceDetailer,
    'negative',
    nodeNames.faceNegative,
    'CONDITIONING',
  );
  workflow = updateNamedNode(workflow, nodeNames.faceDetailer, (node) => {
    let next = setGenerationWidgetValue(node, 0, Math.round(finiteNumber(form.faceGuideSize, 768)), 'guide_size');
    next = setGenerationWidgetValue(next, 2, Math.round(finiteNumber(form.faceMaxSize, 1024)), 'max_size');
    next = setGenerationWidgetValue(next, 3, Math.round(finiteNumber(resolvedSeed, 0)), 'seed');
    next = setGenerationWidgetValue(next, 5, Math.round(finiteNumber(form.faceSteps, 15)), 'steps');
    next = setGenerationWidgetValue(next, 6, finiteNumber(form.faceCfg, 5), 'cfg');
    next = setGenerationWidgetValue(next, 7, form.sampler, 'sampler_name');
    next = setGenerationWidgetValue(next, 8, form.scheduler, 'scheduler');
    next = setGenerationWidgetValue(next, 9, finiteNumber(form.faceDenoise, 0.35), 'denoise');
    return setGenerationWidgetValue(next, 13, finiteNumber(form.faceBBoxThreshold, 0.5), 'bbox_threshold');
  });

  workflow = setMode(workflow, nodeNames.upscaleModel, form.upscaleEnabled ? 0 : 4);
  workflow = setMode(workflow, nodeNames.upscale, form.upscaleEnabled ? 0 : 4);
  workflow = updateNamedNode(workflow, nodeNames.upscaleModel, (node) =>
    setGenerationWidgetValue(node, 0, form.upscaleModel, 'model_name'));
  workflow = updateNamedNode(workflow, nodeNames.saveImage, (node) =>
    setGenerationWidgetValue(
      node,
      0,
      form.upscaleEnabled
        ? `%date:yyyyMMdd%_upscale/${options.outputPrefix}`
        : `%date:yyyyMMdd%_normal/${options.outputPrefix}`,
      'filename_prefix',
    ));

  return workflow;
}

/** Apply the form to a cloned SDXL mobile workflow. */
export function applyGenerationFormToWorkflow(
  form: GenerationFormState,
  sourceWorkflow: Workflow,
  resolvedSeed: number = form.seed,
): Workflow {
  return applyGenerationFormToWorkflowInternal(form, sourceWorkflow, {
    modelWidgetName: 'ckpt_name',
    outputPrefix: 'mobile_sdxl',
  }, resolvedSeed);
}

/** Apply the shared form to the SDXL canonical workflow. */
export function applyGenerationFormToSdxlWorkflow(
  form: GenerationFormState,
  sourceWorkflow: Workflow,
  resolvedSeed: number = form.seed,
): Workflow {
  return applyGenerationFormToWorkflow(form, sourceWorkflow, resolvedSeed);
}

/**
 * Apply the form to the native Anima workflow.
 *
 * Anima is a split-file model: the model, Qwen text encoder, and Qwen Image VAE
 * are separate loader nodes. The feature branches (LoRA, Hires, FaceDetailer,
 * and upscaler) can share the normal ComfyUI sockets, but their loader boundary
 * must be mapped explicitly instead of treating Anima as a CheckpointLoader
 * alias.
 */
export function applyGenerationFormToAnimaWorkflow(
  form: GenerationFormState,
  sourceWorkflow: Workflow,
  resolvedSeed: number = form.seed,
): Workflow {
  const workflow = applyGenerationFormToWorkflowInternal(form, sourceWorkflow, {
    modelWidgetName: 'unet_name',
    outputPrefix: 'mobile_anima',
  }, resolvedSeed);
  return applyAnimaNativeNodeMapping(workflow, form);
}

function applyAnimaNativeNodeMapping(workflow: Workflow, form: GenerationFormState): Workflow {
  const { nodeNames } = getMobileGenerationProfile(workflow);
  let next = updateNamedNode(workflow, nodeNames.checkpoint, (node) =>
    setGenerationWidgetValue(node, 0, form.checkpoint, 'unet_name'));

  // The first LoRA is the adapter boundary between the native Anima loaders
  // and the shared feature graph. Reassert these edges so a restored or edited
  // workflow cannot accidentally send a checkpoint CLIP/VAE into Anima.
  next = replaceNamedWorkflowInputLink(
    next,
    nodeNames.loraSlots[0],
    'model',
    nodeNames.checkpoint,
    'MODEL',
  );
  next = replaceNamedWorkflowInputLink(
    next,
    nodeNames.loraSlots[0],
    'clip',
    nodeNames.textEncoder,
    'CLIP',
  );

  for (const targetName of [
    nodeNames.vaeDecode,
    nodeNames.hiresResizeDecode,
    nodeNames.hiresResizeEncode,
    nodeNames.faceDetailer,
  ]) {
    next = replaceNamedWorkflowInputLink(next, targetName, 'vae', nodeNames.vaeLoader, 'VAE');
  }

  return next;
}

function replaceNamedWorkflowInputLink(
  workflow: Workflow,
  targetName: string,
  targetInputName: string,
  sourceName: string,
  sourceOutputName: string,
): Workflow {
  const target = findMobileNode(workflow, targetName);
  const source = findMobileNode(workflow, sourceName);
  if (!target || !source) return workflow;

  const targetInputSlot = target.inputs.findIndex((input) => input.name === targetInputName);
  const sourceOutputSlot = source.outputs.findIndex((output) => output.name === sourceOutputName);
  if (targetInputSlot < 0 || sourceOutputSlot < 0) return workflow;

  return replaceWorkflowInputLink(
    workflow,
    target.id,
    targetInputSlot,
    source.id,
    sourceOutputSlot,
  );
}

function updateLegacyHiresSwitches(
  workflow: Workflow,
  nodeNames: ReturnType<typeof getMobileGenerationProfile>['nodeNames'],
  form: GenerationFormState,
): Workflow {
  let next = setMode(workflow, nodeNames.hiresMode, 0);
  next = updateNamedNode(next, nodeNames.hiresMode, (node) =>
    setGenerationWidgetValue(node, 0, form.hiresMode === 'resize', 'switch'));
  next = setMode(next, nodeNames.hiresResultSelect, 0);
  return updateNamedNode(next, nodeNames.hiresResultSelect, (node) =>
    setGenerationWidgetValue(node, 0, form.hiresEnabled, 'switch'));
}
